INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱允炆", "aliases": ["明惠帝"], "era": "明", "birth_year": null, "death_year": null, "description": "明惠帝。洪武31年（年号对照1398年），本表记录了朱允炆的活动。", "biography": null, "status": "draft", "id": "76ea9485-acac-508c-a6ae-e2532462c03e"}, {"status": "draft", "name": "朱元璋", "aliases": [], "era": "元末明初", "birth_year": null, "death_year": null, "description": "钟离人，少因饥疫丧家出家皇觉寺，1352年投郭子兴于濠州，后娶其养女。", "biography": null, "id": "3d83c7c6-23fc-5e89-9e9b-b70713a0a63e"}, {"name": "齐泰", "aliases": ["齊泰"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，洪武31年（年号对照1398年）五月，齐泰出任兵部尚书，参与处理国家政务。", "biography": null, "status": "draft", "id": "6ffd1a4d-05e3-5c22-a9b8-c44a7ea23c0e"}, {"name": "朱标", "aliases": ["朱標"], "era": "明", "birth_year": null, "death_year": null, "description": "明太祖时的皇太子。本纪记其于洪武二十五年去世。", "biography": null, "status": "draft", "id": "5c5e855f-d901-54a9-80ba-9dfe24f7c9f9"}, {"name": "吕氏（懿文太子妃）", "aliases": ["呂氏（懿文太子妃）"], "era": "明", "birth_year": null, "death_year": null, "description": "朱标之妃，朱允炆生母。", "biography": null, "status": "draft", "id": "6a355b7e-96ef-5a91-9ceb-fc8ffe0e9590"}]'::jsonb)
