INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朱允炆被立为皇太孙", "description": "朱元璋立皇孙朱允炆为皇太孙。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十五年九月庚寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a74b307e-2cb9-5f99-b49e-8e21a3b4c7c2"}, {"title": "明廷重新制定藩王拜见东宫的礼仪", "description": "洪武二十九年，朝廷重新规定诸王拜见东宫的礼仪。因诸王都是朱允炆的尊长亲属，朝见后在内殿按家人之礼相见。 按原历纪年，事情发生在公元1396至1397年之间。", "start_year": null, "end_year": null, "time_original": "洪武二十九年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "883b625f-94f7-516c-8fca-509c78986820"}, {"title": "朱元璋在西宫去世", "description": "朱元璋在西宫去世，本纪记年龄为七十一。", "start_year": 1398, "end_year": 1398, "time_original": "洪武三十一年闰五月乙酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "987e40aa-7934-5658-aacb-99979d5064e0"}, {"title": "朱允炆即皇帝位", "description": "洪武31年（年号对照1398年）闰五月，朱允炆即皇帝位。", "start_year": 1398, "end_year": 1398, "time_original": "洪武31年（年号对照1398年）闰五月；公元年核为1398年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "c5e84608-ece6-5772-978f-41f88cebe620"}, {"title": "朱允炆大赦并定次年为建文元年", "description": "朱允炆即位后大赦天下，宣布次年为建文元年。", "start_year": 1398, "end_year": 1398, "time_original": "洪武三十一年闰五月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d17fe877-0013-525a-a68f-875414597a57"}, {"title": "朱元璋葬于孝陵", "description": "朱元璋葬于孝陵，谥号为高皇帝，庙号为太祖。", "start_year": 1398, "end_year": 1398, "time_original": "洪武三十一年闰五月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6f327147-bd5a-5d73-b55c-8599a38e8e70"}, {"title": "朱允炆下令行三年丧", "description": "朱允炆下诏按三年之丧行礼，群臣请求依以日代月的方式缩短丧期。朱允炆说明其朝会、退居及祭礼的办法，并要求拟定仪程。", "start_year": 1398, "end_year": 1398, "time_original": "洪武三十一年闰五月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7a78c08b-fb23-54d5-80ab-a7288082c232"}, {"title": "朱允炆命文臣和州县官荐举人才", "description": "朱允炆命五品以上文官和州县官各自荐举人才，举荐不当者要承担责任。", "start_year": 1398, "end_year": 1398, "time_original": "洪武三十一年闰五月丙申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "64d8fd58-8238-5746-86f2-2c516611fcd6"}, {"title": "明廷合并部分州县并裁减冗员", "description": "本纪记载，六月朝廷裁并部分州县，减少冗员。", "start_year": 1398, "end_year": 1398, "time_original": "洪武三十一年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "02758f02-d040-525b-a4f5-94de2339f6a2"}, {"title": "齐泰出任兵部尚书，参与处理国家政务", "description": "洪武31年（年号对照1398年）五月，齐泰出任兵部尚书，参与处理国家政务。", "start_year": 1398, "end_year": 1398, "time_original": "洪武31年（年号对照1398年）五月；公元年核为1398年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "9bbe0b8d-aa58-551c-a139-7c758b3fdad8"}, {"title": "黄子澄出任太常卿并参与军国事务", "description": "翰林院修撰黄子澄出任太常卿，并与齐泰一同参与军国事务。", "start_year": 1398, "end_year": 1398, "time_original": "洪武三十一年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "62628401-2613-53a0-b3ae-64d022628baa"}, {"title": "方孝孺被召为翰林院侍讲", "description": "本纪于秋七月记召汉中府教授方孝孺为翰林院侍讲；卷末校记指出，若干其他记载将此事列在六月。", "start_year": 1398, "end_year": 1398, "time_original": "洪武三十一年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d70c3a60-104c-5f02-b52a-b6641e8ad3ad"}, {"title": "明廷施行宽政并免收积欠赋税", "description": "朝廷下诏实行宽政，赦免有罪者，免除积欠的赋税。", "start_year": 1398, "end_year": 1398, "time_original": "洪武三十一年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e7134ffe-4b22-584e-9489-b7e64323470f"}, {"title": "周王朱橚被废为庶人并迁云南", "description": "周王朱橚获罪，被废为庶人，并迁往云南。", "start_year": 1398, "end_year": 1398, "time_original": "洪武三十一年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "85936d8a-d261-5893-9157-c548c100bbb4"}, {"title": "明廷准部分卫所军户减役", "description": "朝廷下诏，兴州、营州、开平各卫全家从军的家庭，免去一人军役；各地卫所军户只有一名男丁的，准许转为平民。", "start_year": 1398, "end_year": 1398, "time_original": "洪武三十一年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3aadf007-b187-52b3-9195-94a79ed57008"}, {"title": "沐春在军中去世，何福接掌其部", "description": "云南总兵官、西平侯沐春在军中去世，由左副将何福接掌其部。", "start_year": 1398, "end_year": 1398, "time_original": "洪武三十一年九月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7223b482-09b5-51b9-80ba-3e4779898d73"}, {"title": "张昺谢贵张信受命掌理北平军政并察燕王动向", "description": "工部侍郎张昺被任为北平布政使，谢贵、张信掌北平都指挥使司，本纪称他们负责察访燕王的秘密行动。 按原历纪年，事情发生在公元1398至1399年之间。", "start_year": null, "end_year": null, "time_original": "洪武三十一年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d7835db6-cfe4-5b6a-8fbf-f64cbf0bccf6"}, {"title": "明廷下诏求直言并荐举隐居者", "description": "朝廷下诏征求直言，并命荐举有才德的隐居之士。 按原历纪年，事情发生在公元1398至1399年之间。", "start_year": null, "end_year": null, "time_original": "洪武三十一年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d99b7ac2-c675-55f4-a10a-e47a766b8893"}, {"title": "何福击败并斩杀刀干孟", "description": "何福率军击败并斩杀刀干孟。麓川战事至此平定。", "start_year": 1399, "end_year": 1399, "time_original": "洪武三十一年十二月癸卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "da10e5f9-4129-505c-8645-7a8d27876d32"}, {"title": "明廷减免次年田租并放还黥军囚徒", "description": "本纪记载，朝廷在这个月减免次年一半田租，释放黥军和囚徒回乡。", "start_year": 1399, "end_year": 1399, "time_original": "洪武三十一年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "663738b4-f854-512b-9922-40d72918ccc4"}, {"title": "暹罗和占城使者入贡", "description": "本纪记载，暹罗与占城在这一年入贡。 按原历纪年，事情发生在公元1398至1399年之间。", "start_year": null, "end_year": null, "time_original": "洪武三十一年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9988981b-1bd5-5ac1-95f5-45a01660c659"}, {"title": "朱允炆受朝时停用礼乐", "description": "朱允炆在正月癸酉接受群臣朝见，仪式没有奏乐。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年正月癸酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "966cf363-9457-535d-892a-9409430f369c"}, {"title": "明廷在南郊祭祀天地并奉太祖配享", "description": "在南郊祭祀天地时，明廷奉明太祖配享。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年正月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "00d27e96-3d00-5e20-a46a-a49b8eda43bb"}, {"title": "明廷修撰《太祖实录》", "description": "本纪记载，明廷在这个月开始修撰《太祖实录》。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0928d4d3-88b7-56c9-ad07-96ccd250c114"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

